{\n
  "additionalProperties": true, \n
  "type": "object", \n
  "description": "Inline base64 file content or an error. The resource_link path returns rich content, not structuredContent.", \n
  "properties": {\n
    "dialog_method": {\n
      "type": "string"\n
    }, \n
    "filename": {\n
      "type": "string"\n
    }, \n
    "note": {\n
      "type": "string"\n
    }, \n
    "content_base64": {\n
      "type": "string"\n
    }, \n
    "content_type": {\n
      "type": "string"\n
    }, \n
    "error": {\n
      "type": "string", \n
      "description": "Error message; present only on failure."\n
    }, \n
    "size": {\n
      "type": "integer"\n
    }\n
  }\n
}

{
 "additionalProperties": false, 
 "required": [
 "relative_url", 
 "action_name"
 ], 
 "type": "object", 
 "properties": {
 "inline": {
 "default": 0, 
 "type": [
 "boolean", 
 "integer"
 ], 
 "description": "Return the file inline as base64 instead of a resource_link (for hosts that can't fetch links, or for tiny files)."
 }, 
 "params": {
 "default": null, 
 "type": [
 "object", 
 "null"
 ], 
 "description": "Dialog params."
 }, 
 "action_type": {
 "default": "exchange", 
 "type": "string", 
 "description": "exchange or print."
 }, 
 "relative_url": {
 "type": "string", 
 "description": "Document path."
 }, 
 "action_name": {
 "type": "string", 
 "description": "Print/exchange action."
 }
 }
 }
